 void RefreshFiles(){if(!fileBody)return;Clear(fileBody);var w=fileBody.rect.width;
  if(folder=="pc"||folder=="network"){
   string[] names=folder=="pc"?new[]{"Рабочий стол","Документы","Загрузки","Рабочие папки (Z:)"}:new[]{"Производство / Рабочие папки"};string[] ids=folder=="pc"?new[]{"desktopfiles","documents","downloads","departments"}:new[]{"departments"};for(int i=0;i<names.Length;i++){string id=ids[i];var b=B(fileBody,"Location · "+names[i],8,18+i*66,w-16,58,"",()=>Navigate(id));Icon(b.transform,i==3?"pc":"folder",10,6,47,47);T(b.transform,names[i],74,17,w-90,30,18);}status.text=names.Length+" элементов";return;
  }
  var list=Listed();if(list.Count==0){T(fileBody,query.Length>0?"Нет элементов, удовлетворяющих условиям поиска.":"Эта папка пуста.",20,80,w-40,60,16,false,gray).alignment=TextAnchor.MiddleCenter;status.text="0 элементов";return;}
  if(details){Panel(fileBody,"Columns",0,0,w,28,new Color32(250,250,250,255));B(fileBody,"Sort by name",7,0,w*.49f,28,"Имя",()=>{descending=!descending;RefreshFiles();},Color.white,gray,13);T(fileBody,"Дата изменения",w*.52f,5,w*.23f,24,13,false,gray);T(fileBody,"Тип",w*.78f,5,w*.22f,24,13,false,gray);}
  int columns=Mathf.Max(1,(int)(w/156));for(int i=0;i<list.Count;i++){var e=list[i];float x=details?6:8+(i%columns)*156,y=details?30+i*31:12+(i/columns)*118;float bw=details?w-12:148,bh=details?30:116;var b=B(fileBody,"Item · "+e.name,x,y,bw,bh,"",()=>{},selected==e.id?new Color32(204,232,255,255):Color.white);var image=b.targetGraphic;var click=b.gameObject.AddComponent<FactoryDesktopClick>();click.itemId=e.id;click.select=()=>SelectEntry(e.id);click.open=()=>OpenItem(e.id);click.context=pos=>ItemContext(e.id,pos);
   if(details){FileGlyph(b.transform,e,4,4,22,22);T(b.transform,DisplayName(e),35,5,bw*.46f,24,14);T(b.transform,"24.10.2026 09:41",bw*.52f,5,bw*.25f,24,13,false,gray);T(b.transform,e.kind=="folder"?"Папка с файлами":e.kind=="photo"?"Изображение PNG":"Документ",bw*.79f,5,bw*.21f,24,13,false,gray);}else{FileGlyph(b.transform,e,40,6,68,58);var label=T(b.transform,DisplayName(e),2,70,144,46,15);label.alignment=TextAnchor.UpperCenter;}
  }
  fileBody.sizeDelta=new Vector2(w,Mathf.Max(details?32+list.Count*31:Mathf.Ceil(list.Count/(float)columns)*118+22,250));status.text=list.Count+" элементов"+(selected.Length>0?"   |   Выбрано: "+DisplayName(Find(selected)):"");
 }
 void SelectEntry(string id){selected=id;foreach(var click in fileBody.GetComponentsInChildren<FactoryDesktopClick>()){var image=click.GetComponent<Image>();if(image)image.color=click.itemId==id?new Color32(204,232,255,255):Color.white;}status.text="Выбрано: "+Name(id);}
 string DisplayName(Entry e)=>e==null?"":extensions||e.kind=="folder"?e.name:System.IO.Path.GetFileNameWithoutExtension(e.name);
 void OpenItem(string id){if(new[]{"pc","trash","departments","desktopfiles","documents","downloads","network"}.Contains(id)){Navigate(id);return;}var e=Find(id);if(e==null)return;if(e.kind=="photo"){OpenPhoto(id);return;}if(e.deleted){selected=id;Properties();return;}if(e.kind=="folder")Navigate(e.id);else OpenNote(e.id);}
 void AddressNavigate(string value){if(value==PathName(folder))return;string q=value.Trim().Replace('\\','>').Replace('/','>').Split('>').Last().Trim();var e=entries.FirstOrDefault(x=>x.kind=="folder"&&(x.name.Equals(q,StringComparison.OrdinalIgnoreCase)||x.id==q));if(e!=null)Navigate(e.id);else if(q.IndexOf("Рабочие папки",StringComparison.OrdinalIgnoreCase)>=0)Navigate("departments");else if(q=="Этот компьютер")Navigate("pc");else Notice("Не удалось найти папку","Проверь название или выбери папку в левой панели.");}
 void Copy(){if(Find(selected)==null){Notice("Копирование","Сначала выбери файл или папку.");return;}clipboard=selected;if(status)status.text="Скопировано: "+Name(selected);}
 void Paste(){var source=Find(clipboard);if(source==null){Notice("Вставка","В буфере пока нет файлов.");return;}if(folder=="pc"||folder=="trash"||folder=="network")return;var snapshot=entries.ToArray();Action<Entry,string,int> clone=null;clone=(e,parent,depth)=>{if(depth>8)return;string id="copy"+(++serial);Add(id,e.name+(depth==0?" — копия":""),parent,e.kind,e.text);Find(id).imageIndex=e.imageIndex;foreach(var child in snapshot.Where(x=>x.parent==e.id&&!x.deleted))clone(child,id,depth+1);};clone(source,folder,0);RefreshFiles();}
 void Rename(){var e=Find(selected);if(e==null){Notice("Переименование","Сначала выбери файл или папку.");return;}if(e.readOnly){Notice("Только чтение","Сними отметку «Только чтение» в свойствах.");return;}TextPrompt("Переименовать",e.name,value=>{if(value.Trim().Length>0)e.name=value.Trim();RenderExplorer();});}
 void NewFolder(){if(folder=="pc"||folder=="trash"||folder=="network")return;TextPrompt("Новая папка","Новая папка",value=>{if(value.Trim().Length>0)Add("new"+(++serial),value.Trim(),folder,"folder");RefreshFiles();});}
 void Delete(){var e=Find(selected);if(e==null){Notice("Удаление","Сначала выбери файл или папку.");return;}if(e.readOnly){Notice("Только чтение","Сними отметку «Только чтение» в свойствах.");return;}e.originalParent=e.parent;e.deleted=true;selected="";RefreshFiles();}
 void Restore(){var e=Find(selected);if(e!=null&&e.deleted){e.deleted=false;e.parent=e.originalParent;RefreshFiles();}}
 void Properties(){var e=Find(selected);string name=e?.name??Name(folder);var r=Popup(name+" — свойства",430,290);T(r,name,24,58,380,45,19);T(r,"Тип: "+(e?.kind=="folder"?"Папка с файлами":"Рабочий документ")+"\nРасположение: "+PathName(e?.parent??folder),24,112,380,88,15);if(e!=null){var read=B(r,"Read only property",24,208,250,30,"",()=>{e.readOnly=!e.readOnly;Properties();});Icon(read.transform,e.readOnly?"checked":"checkbox",0,5,18,18);T(read.transform,"Только чтение",28,5,210,24,15);}B(r,"Properties OK",302,240,104,32,"OK",Dismiss,new Color32(238,238,238,255));}
 void TextPrompt(string title,string value,Action<string> accepted){var r=Popup(title,430,206);var input=EditField(r,title,22,66,386,34,value,s=>{});B(r,"Accept name",186,144,104,34,"OK",()=>{accepted(input.text);Dismiss();},new Color32(238,238,238,255));B(r,"Cancel name",302,144,104,34,"Отмена",Dismiss,new Color32(238,238,238,255));input.ActivateInputField();}
 void Notice(string title,string message){Dialog(title,message,new[]{("OK",(Action)Dismiss)});}
 void FileMenu(){Dialog("Файл","Действия Проводника",new[]{("Рабочие папки",(Action)(()=>Navigate("departments"))),("Свойства",(Action)Properties),("Закрыть",(Action)(()=>{Dismiss();CloseExplorer();}))});}
 void ContextMenu(string id,Vector2 pos,bool desktopItem=false){
  Dismiss();HideStart();selected=id;RectTransformUtility.ScreenPointToLocalPointInRectangle(screen,pos,null,out var local);float x=Mathf.Clamp(local.x,0,SW-230),y=Mathf.Clamp(-local.y,0,SH-TB-174);popup=Panel(screen,"Context menu",x,y,230,174,Color.white);popup.gameObject.AddComponent<Outline>().effectColor=border;
  (string,Action)[] actions=desktopItem?new[]{("Открыть",(Action)(()=>{Dismiss();if(id=="welcome")OpenNote(id);else Navigate(id);})),("Свойства",(Action)Properties)}:new[]{("Открыть",(Action)(()=>{Dismiss();OpenItem(id);})),("Копировать",(Action)(()=>{Dismiss();Copy();})),("Переименовать",(Action)Rename),("Удалить",(Action)(()=>{Dismiss();Delete();})),("Свойства",(Action)Properties)};
  for(int i=0;i<actions.Length;i++){var action=actions[i];var button=B(popup,"Context · "+action.Item1,2,2+i*33,226,32,action.Item1,action.Item2,Color.white,ink,15);button.GetComponentInChildren<Text>().alignment=TextAnchor.MiddleLeft;button.GetComponentInChildren<Text>().rectTransform.anchoredPosition=new Vector2(24,0);}
 }
 void ItemContext(string id,Vector2 pos){ContextMenu(id,pos);}
 void DesktopContext(string id,Vector2 pos){ContextMenu(id,pos,true);}
}
